mapper.select:
SELECT icam11_fee_deposit_id AS fee_deposit_id, icam11_icam_company_cd AS icam_company_code, NULL::varchar AS icam_company_name, icam11_fund_cd AS fund_code, NULL::varchar AS fund_name, NULL::varchar AS cur_code, NULL::varchar AS consignment_name, icam11_deposit_id AS deposit_id, ast01_class_tree_nm AS deposit_name, icam11_start_date AS start_date FROM icam11_fee_deposit LEFT OUTER JOIN ast01_class_tree ON ast01_class_tree_id = icam11_deposit_id WHERE icam11_company_id = #{companyId} AND icam11_fund_cd = #{fundCode}
AND icam11_icam_company_cd = #{icamCompanyCode}
ORDER BY icam11_start_date

mapper.update:
UPDATE icam11_fee_deposit
   SET icam11_start_date = #{r.startDate},
       icam11_deposit_id = #{r.depositId}
 WHERE icam11_fee_deposit_id = #{r.feeDepositId}
   AND icam11_company_id     = #{companyId}

mapper.delete:
DELETE FROM icam11_fee_deposit
 WHERE icam11_company_id = #{companyId}
   AND icam11_fee_deposit_id IN
#{id}
